{
  "findings": [
    {
      "check_id": "CKV_AWS_1",
      "title": "IAM Policy allows wildcard resource for SageMaker actions",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "HIGH",
      "explanation": "The policy grants 'sagemaker:CreatePresignedNotebookInstanceUrl' and 'sagemaker:ListNotebookInstances' on all resources ('*'). This violates the principle of least privilege, allowing users to generate presigned URLs for any notebook instance in the account, potentially leading to unauthorized access or data exfiltration."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows privesc via sagemakerCreatePresignedNotebookURL"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl",
          "sagemaker:ListNotebookInstances"
        ]
        Resource = "arn:aws:sagemaker:*:*:notebook-instance/*"
      },
    ]
  })
}",
  "fix_summary": "Replaced the wildcard '*' in the Resource field with a specific ARN pattern for SageMaker notebook instances ('arn:aws:sagemaker:*:*:notebook-instance/*') to restrict the scope of the permissions while maintaining functionality for listing and creating presigned URLs for notebooks."
}
